-- ============================================ ABAC: atributos y reglas
-- Catálogo de atributos y reglas por capacidad. El código que decide está
-- en src/features/seguridad/lib/abac.ts; la base evalúa lo mismo en
-- public.puede_contexto(u, clave, ctx), para que la policy y la UI den
-- la misma respuesta. Si se edita una regla, se regenera este archivo.

-- 8 atributos, 18 reglas.

-- ------------------------------------------------------------- atributos

-- ----------------------------------------------------------------- reglas
-- `condicion` lleva el operador y el valor esperados, para que la base
-- pueda evaluarla sin volver aárbol TypeScript.
select 'ticket:anular:estado_abierto', c.id, 'global', a.id, '{"operador":"en","valor":["CREADO","EN_REVISION"]}'::jsonb, 'denegar', 'Este ticket ya fue solucionado. No se puede volver a resolver.', 'integridad', false, 'critico', 'src/lib/tickets.ts:resolverTicket'
from public.capacidad c, public.atributo a
where c.clave = 'tickets:fn_anular_ticket' and a.clave = 'estado'
on conflict (id) do update set capacidad_id = excluded.capacidad_id, ambito = excluded.ambito, atributo_id = excluded.atributo_id, condicion = excluded.condicion, efecto = excluded.efecto, mensaje = excluded.mensaje, clase = excluded.clase, principal_exento = excluded.principal_exento, riesgo = excluded.riesgo, fuente = excluded.fuente;
select 'ticket:anular:accion_valida', c.id, 'global', a.id, '{"operador":"en","valor":["ABONO","REEMBOLSO","AJUSTE","RECHAZO"]}'::jsonb, 'denegar', 'La acción indicada no es una resolución válida de ticket.', 'integridad', false, 'critico', 'src/lib/tickets.ts:resolverTicket'
from public.capacidad c, public.atributo a
where c.clave = 'tickets:fn_anular_ticket' and a.clave = 'accion'
on conflict (id) do update set capacidad_id = excluded.capacidad_id, ambito = excluded.ambito, atributo_id = excluded.atributo_id, condicion = excluded.condicion, efecto = excluded.efecto, mensaje = excluded.mensaje, clase = excluded.clase, principal_exento = excluded.principal_exento, riesgo = excluded.riesgo, fuente = excluded.fuente;
select 'liquidar:hipodromo_propio', c.id, 'tipo:operador', a.id, '{"operador":"en_atributo","valor":"usuario_hipodromos"}'::jsonb, 'denegar', 'Ese hipódromo no está asignado a tu usuario. Pedile a un administrador que lo cargue.', 'integridad', false, 'critico', 'src/lib/gestion_jugadas.ts:liquidarCarrera'
from public.capacidad c, public.atributo a
where c.clave = 'gestion_jugadas:fn_liquidar_carrera' and a.clave = 'hipodromo'
on conflict (id) do update set capacidad_id = excluded.capacidad_id, ambito = excluded.ambito, atributo_id = excluded.atributo_id, condicion = excluded.condicion, efecto = excluded.efecto, mensaje = excluded.mensaje, clase = excluded.clase, principal_exento = excluded.principal_exento, riesgo = excluded.riesgo, fuente = excluded.fuente;
select 'liquidar:tope_operador', c.id, 'tipo:operador', a.id, '{"operador":"entre","valor":[0,5000]}'::jsonb, 'permitir', 'La liquidación supera los 5.000: la tiene que firmar un administrador.', 'limite', true, 'critico', 'src/lib/gestion_jugadas.ts:liquidarCarrera'
from public.capacidad c, public.atributo a
where c.clave = 'gestion_jugadas:fn_liquidar_carrera' and a.clave = 'monto'
on conflict (id) do update set capacidad_id = excluded.capacidad_id, ambito = excluded.ambito, atributo_id = excluded.atributo_id, condicion = excluded.condicion, efecto = excluded.efecto, mensaje = excluded.mensaje, clase = excluded.clase, principal_exento = excluded.principal_exento, riesgo = excluded.riesgo, fuente = excluded.fuente;
select 'retiros:monto_no_negativo', c.id, 'global', a.id, '{"operador":"entre","valor":[0,25000]}'::jsonb, 'permitir', 'El retiro debe estar entre 0 y 25.000.', 'integridad', false, 'critico', 'src/lib/gestion_jugadas.ts:aplicarRetiros'
from public.capacidad c, public.atributo a
where c.clave = 'gestion_jugadas:fn_aplicar_retiros' and a.clave = 'monto'
on conflict (id) do update set capacidad_id = excluded.capacidad_id, ambito = excluded.ambito, atributo_id = excluded.atributo_id, condicion = excluded.condicion, efecto = excluded.efecto, mensaje = excluded.mensaje, clase = excluded.clase, principal_exento = excluded.principal_exento, riesgo = excluded.riesgo, fuente = excluded.fuente;
select 'retiros:hipodromo_propio', c.id, 'tipo:operador', a.id, '{"operador":"en_atributo","valor":"usuario_hipodromos"}'::jsonb, 'denegar', 'Ese hipódromo no está asignado a tu usuario.', 'integridad', false, 'critico', 'src/lib/gestion_jugadas.ts:aplicarRetiros'
from public.capacidad c, public.atributo a
where c.clave = 'gestion_jugadas:fn_aplicar_retiros' and a.clave = 'hipodromo'
on conflict (id) do update set capacidad_id = excluded.capacidad_id, ambito = excluded.ambito, atributo_id = excluded.atributo_id, condicion = excluded.condicion, efecto = excluded.efecto, mensaje = excluded.mensaje, clase = excluded.clase, principal_exento = excluded.principal_exento, riesgo = excluded.riesgo, fuente = excluded.fuente;
select 'contabilidad:metodo_pago_valido', c.id, 'global', a.id, '{"operador":"en","valor":["efectivo","transferencia","pago movil","divisa","paypal","zelle","binance","otro"]}'::jsonb, 'denegar', 'Método de pago no reconocido.', 'integridad', false, 'critico', 'src/lib/contabilidad.ts:registrarMovimiento'
