-- ------- retirar reglas que el código ya no declara (mismo criterio que
--         las capacidades: si la regla no está en el registro, se va)
delete from public.regla_abac r
where not exists (select 1 from unnest(array['ticket:anular:estado_abierto', 'ticket:anular:accion_valida', 'liquidar:hipodromo_propio', 'liquidar:tope_operador', 'retiros:monto_no_negativo', 'retiros:hipodromo_propio', 'contabilidad:metodo_pago_valido', 'contabilidad:tope_operador', 'hipodromos:guardar_propio', 'hipodromos:eliminar_propio', 'clientes:guardar:mismo_grupo', 'clientes:guardar:mismo_grupo_banquero', 'clientes:eliminar:mismo_grupo', 'clientes:eliminar:mismo_grupo_banquero', 'grupos:guardar:mismo_grupo', 'grupos:guardar:mismo_grupo_banquero', 'contabilidad:mismo_grupo', 'contabilidad:mismo_grupo_banquero']::text[]) as v(id) where v.id = r.id);
